'use strict';
function modal(message,initial,isPrompt){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='small-dialog';const label=document.createElement('label');label.textContent=message;label.style.cssText='display:block;white-space:pre-wrap;line-height:1.9;margin-bottom:18px';d.append(label);let input;if(isPrompt){input=document.createElement('input');input.value=initial||'';input.style.cssText='width:100%;margin-bottom:18px';label.htmlFor='modalInput';input.id='modalInput';d.append(input);}const row=document.createElement('div');row.style.cssText='display:flex;justify-content:flex-end;gap:8px';const cancel=document.createElement('button'),ok=document.createElement('button');cancel.textContent='취소';ok.textContent='확인';ok.className='primary';row.append(cancel,ok);d.append(row);document.body.append(d);let done=false;function finish(value){if(done)return;done=true;d.close();d.remove();resolve(value);}ok.onclick=()=>finish(isPrompt?input.value:true);cancel.onclick=()=>finish(isPrompt?null:false);d.oncancel=e=>{e.preventDefault();finish(isPrompt?null:false);};if(input)input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();ok.click();}};d.showModal();if(input){input.focus();input.select();}});}
const ask=(message,initial='')=>modal(message,initial,true),confirmAction=message=>modal(message,'',false);

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2), KEY='galpi-experience-v1';
const bank=[['동기','나는 어떤 문제를 해결할 때 가장 몰입하는가?'],['동기','이 기업에 지원하는 이유는 무엇인가?'],['동기','이 직무를 선택하게 된 계기는 무엇인가?'],['동기','앞으로 3년 안에 어떤 역량을 키우고 싶은가?'],['경험','가장 주도적으로 문제를 해결한 경험은?'],['경험','실패한 뒤 접근 방식을 바꾼 경험은?'],['경험','의견이 다른 사람과 어떻게 합의했는가?'],['경험','제한된 시간과 자원에서 무엇을 우선했는가?'],['학부','전공 프로젝트에서 내가 맡은 역할은?'],['학부','수업 밖에서 스스로 배우고 실행한 일은?'],['학부','팀 프로젝트의 성과를 어떻게 설명할 수 있는가?'],['석사','연구 질문은 무엇이며 왜 중요한가?'],['석사','기존 연구의 한계를 어떻게 발견했는가?'],['석사','실험이 예상과 다를 때 어떻게 검증했는가?'],['석사','연구를 실제 제품이나 서비스에 어떻게 적용할 수 있는가?'],['스타트업','고객의 문제를 어떤 근거로 확인했는가?'],['스타트업','불확실한 상황에서 어떤 가설을 먼저 검증했는가?'],['스타트업','적은 자원으로 성과를 만든 방법은?'],['스타트업','제품 방향을 바꾼 결정과 배운 점은?'],['직무','이 직무에 필요한 핵심 역량을 증명할 경험은?'],['직무','기술적 선택의 대안과 트레이드오프는 무엇이었는가?'],['직무','협업할 때 결과물의 품질을 어떻게 지키는가?'],['직무','성과를 어떤 수치나 결과물로 보여줄 수 있는가?'],['기업별','이 기업의 제품·고객·사업을 어떻게 이해하고 있는가?'],['기업별','이 기업의 과제와 내 경험이 만나는 지점은?'],['기업별','입사 후 가장 먼저 기여할 수 있는 일은?']];
const starter=()=>({version:1,categories:[{id:'motivation',name:'동기',parent:null},{id:'experience',name:'경험',parent:null},{id:'undergrad',name:'학부',parent:'experience'},{id:'master',name:'석사',parent:'experience'},{id:'startup',name:'스타트업',parent:'experience'},{id:'role',name:'직무',parent:null},{id:'company',name:'기업별',parent:null}],columns:[],nodes:[{id:'start',parent:null,type:'question',category:'experience',title:'나를 가장 잘 보여주는 경험은?',body:'',tags:['나의 강점'],x:65,y:220,fields:{}},{id:'a',parent:'start',type:'answer',category:'undergrad',title:'학부에서의 경험',body:'',tags:['협업'],x:390,y:65,fields:{}},{id:'b',parent:'start',type:'answer',category:'master',title:'석사에서의 경험',body:'',tags:['문제 해결'],x:390,y:285,fields:{}},{id:'c',parent:'start',type:'answer',category:'startup',title:'스타트업에서의 경험',body:'',tags:['실행력'],x:390,y:505,fields:{}}]});
let data=starter(),selected='start',category=null,view='map',query='',bankFilter='전체',history=[];
function validate(d){if(!d||d.version!==1||!Array.isArray(d.nodes)||!Array.isArray(d.categories)||!Array.isArray(d.columns))throw Error('갈피에서 저장한 버전 1 JSON 파일을 선택해 주세요.');if(!d.categories.length)throw Error('카테고리가 하나 이상 필요합니다.');if(d.nodes.length>3000||d.categories.length>300||d.columns.length>100)throw Error('파일에 항목이 너무 많습니다.');const unique=a=>a.length===new Set(a.map(n=>n.id)).size;const str=x=>typeof x==='string';if(!unique(d.nodes)||!unique(d.categories)||!unique(d.columns))throw Error('중복된 항목 ID가 있습니다.');for(const c of d.categories)if(!str(c.id)||!str(c.name)||(c.parent!==null&&!d.categories.some(p=>p.id===c.parent)))throw Error('카테고리 형식이 올바르지 않습니다.');for(const c of d.columns)if(!str(c.id)||!str(c.name)||['__proto__','constructor','prototype'].includes(c.id))throw Error('열 형식이 올바르지 않습니다.');for(const n of d.nodes)if(!str(n.id)||!str(n.title)||!str(n.body)||!['question','answer'].includes(n.type)||!Array.isArray(n.tags)||!n.tags.every(str)||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.y<0||n.x>100000||n.y>100000||!n.fields||typeof n.fields!=='object'||Array.isArray(n.fields)||!Object.values(n.fields).every(str)||!d.categories.some(c=>c.id===n.category)||(n.parent!==null&&!d.nodes.some(p=>p.id===n.parent)))throw Error('노드 형식 또는 연결이 올바르지 않습니다.');for(const list of [d.nodes,d.categories])for(const item of list){let seen=new Set(),p=item;while(p){if(seen.has(p.id))throw Error('순환 연결이 있는 파일입니다.');seen.add(p.id);p=list.find(x=>x.id===p.parent);}}return d;}
try{const raw=localStorage.getItem(KEY);if(raw)data=validate(JSON.parse(raw));}catch(e){setTimeout(()=>toast('기존 자동 저장을 읽지 못했습니다. JSON 백업을 불러올 수 있습니다.'),300);}
selected=data.nodes[0]?.id;
function persist(){data.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(data));$('#saveStatus').textContent='● 브라우저에 저장됨';}catch{$('#saveStatus').textContent='저장 실패 · JSON 저장 필요';toast('자동 저장 공간이 부족하거나 차단되었습니다. JSON으로 저장해 주세요.');}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200);}
function checkpoint(){history.push(JSON.stringify(data));if(history.length>30)history.shift();}
function changed(){persist();render();}
const node=()=>data.nodes.find(n=>n.id===selected), catName=id=>data.categories.find(c=>c.id===id)?.name||'미분류';
function descendants(id,list){const ids=new Set([id]);let more=true;while(more){more=false;for(const x of list)if(ids.has(x.parent)&&!ids.has(x.id)){ids.add(x.id);more=true;}}return ids;}
function visible(){const cats=category?descendants(category,data.categories):null;return data.nodes.filter(n=>(!cats||cats.has(n.category))&&(!query||[n.title,n.body,...n.tags,...Object.values(n.fields)].join(' ').toLowerCase().includes(query.toLowerCase())));}
function catOptions(value){return data.categories.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${c.parent?esc(catName(c.parent))+' / ':''}${esc(c.name)}</option>`).join('');}
function render(){renderSidebar();renderBoard();if(view==='table')renderTable();renderEditor();$('#stats').textContent=`${visible().length}개 표시 · 전체 ${data.nodes.length}개 기록`;$('#mapTab').classList.toggle('selected',view==='map');$('#tableTab').classList.toggle('selected',view==='table');$('#viewport').hidden=view!=='map';$('#tableView').hidden=view!=='table';$('#arrange').hidden=view!=='map';$('#addColumn').hidden=view!=='table';$('#viewHint').textContent=view==='map'?'카드를 드래그해 이동 · 카드를 선택해 글쓰기 · 키워드를 다른 카드로 이동':'셀을 클릭해 바로 편집 · 열 추가로 나만의 정리 항목 만들기';}
function renderSidebar(){$('#count').textContent=data.nodes.length;$('#all').classList.toggle('active',!category);$('#crumb').textContent=category?catName(category):'모든 경험';let html='';function branch(parent,depth=0){for(const c of data.categories.filter(c=>c.parent===parent)){const num=data.nodes.filter(n=>descendants(c.id,data.categories).has(n.category)).length;html+=`<div class="cat-row" style="padding-left:${depth*12}px"><button class="nav ${c.id===category?'active':''}" data-cat="${esc(c.id)}">${depth?'↳':'▱'} &nbsp; ${esc(c.name)} <span>${num}</span></button><button class="cat-edit" data-edit-cat="${esc(c.id)}" title="카테고리 이름 변경">⋯</button></div>`;branch(c.id,depth+1);}}branch(null);$('#categories').innerHTML=html;}
function renderBoard(){const list=visible();$('#empty').hidden=!!list.length;$('#nodes').innerHTML=list.map(n=>`<article tabindex="0" role="button" aria-label="${esc(n.title)} 편집" class="node ${n.type} ${n.id===selected?'selected':''}" data-id="${esc(n.id)}" style="left:${n.x}px;top:${n.y}px"><div class="node-type"><i></i>${n.type==='question'?'질문':'경험 · 답변'} <span> / ${esc(catName(n.category))}</span></div><h3>${esc(n.title||'제목 없는 기록')}</h3><p>${esc(n.body||'클릭해서 나의 이야기를 적어보세요.')}</p><div class="tags">${n.tags.map((t,i)=>`<span draggable="true" class="tag" data-tag="${i}">${esc(t)}</span>`).join('')}</div><button class="node-plus" title="연결된 답변 추가" data-add="${esc(n.id)}">+</button></article>`).join('');$('#board').style.width=Math.max(1100,...list.map(n=>n.x+340))+'px';$('#board').style.height=Math.max(900,...list.map(n=>n.y+330))+'px';drawLines();}
function drawLines(){const list=visible();$('#lines').innerHTML=list.filter(n=>list.some(p=>p.id===n.parent)).map(n=>{const p=list.find(p=>p.id===n.parent),x=p.x+238,y=p.y+65,x2=n.x,y2=n.y+65;return `<path d="M${x} ${y} C${x+65} ${y},${x2-65} ${y2},${x2} ${y2}" fill="none" stroke="#becdb3" stroke-width="1.4"/>`;}).join('');}
function renderEditor(){const n=node();if(!n){$('#editor').innerHTML='<div class="empty-editor">✳<br>기록 하나를 선택하면<br>이곳에서 이야기를 이어갈 수 있어요.</div>';return;}const dis=descendants(n.id,data.nodes);$('#editor').innerHTML=`<h2>이야기 다듬기</h2><div class="eyebrow">ONE PIECE OF YOUR STORY</div><label for="editTitle">제목</label><input id="editTitle" value="${esc(n.title)}" placeholder="어떤 경험인가요?"><div class="row"><div style="flex:1"><label for="editType">종류</label><select id="editType"><option value="question" ${n.type==='question'?'selected':''}>질문</option><option value="answer" ${n.type==='answer'?'selected':''}>경험 · 답변</option></select></div><div style="flex:1"><label for="editCat">카테고리</label><select id="editCat">${catOptions(n.category)}</select></div></div><label for="editParent">연결할 상위 기록</label><select id="editParent"><option value="">연결 없음 · 시작 노드</option>${data.nodes.filter(p=>!dis.has(p.id)).map(p=>`<option value="${esc(p.id)}" ${n.parent===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select><label for="editBody">나의 기록</label><textarea id="editBody" placeholder="상황과 목표는 무엇이었나요?&#10;내가 직접 한 행동은?&#10;결과와 배운 점은?">${esc(n.body)}</textarea><label>키워드</label><div id="editorTags">${n.tags.map((t,i)=>`<span class="tag">${esc(t)}<button data-remove-tag="${i}" aria-label="${esc(t)} 키워드 삭제">×</button></span>`).join('')}</div><div class="row" style="margin-top:8px"><input id="tagInput" placeholder="키워드 입력" aria-label="새 키워드"><button id="addTag">＋</button></div><p class="note">지도에서 키워드를 다른 카드로 끌어 옮길 수 있어요.</p><button class="action primary" id="childAnswer">＋ 답변 연결하기</button><button class="action" id="childQuestion">＋ 꼬리질문 연결하기</button><div class="guide"><div class="eyebrow">조금 더 깊이 생각해 보기</div>${['내가 직접 맡은 역할은?','가장 어려웠던 점과 해결 방법은?','결과를 보여주는 근거는?','이 경험에서 무엇을 배웠는가?'].map(t=>`<button data-follow="${esc(t)}">↳ ${esc(t)}</button>`).join('')}</div><button class="action danger" id="deleteNode">이 기록 삭제</button><p class="note">삭제하면 하위 기록은 시작 노드로 남습니다.<br>Ctrl / ⌘ + Z : 마지막 구조 변경 되돌리기</p>`;}
function addNode(parent=null,type='question',title){checkpoint();const p=data.nodes.find(n=>n.id===parent);const siblings=data.nodes.filter(n=>n.parent===parent);const id=uid();data.nodes.push({id,parent,type,category:category||p?.category||data.categories[0].id,title:title||(type==='question'?'새 질문':'새 경험 · 답변'),body:'',tags:[],x:p?p.x+325:65,y:p?p.y+siblings.length*195:65+siblings.length*195,fields:{}});selected=id;query='';$('#search').value='';changed();if(view==='map'){const n=node();$('#viewport').scrollTo({left:Math.max(0,n.x-40),top:Math.max(0,n.y-50),behavior:'smooth'});}$('#editTitle').focus();$('#editTitle').select();}
function renderTable(){const list=visible();$('#tableView').innerHTML=`<table><thead><tr><th>편집</th><th>제목</th><th>종류</th><th>카테고리</th><th>내용</th><th>키워드 (쉼표로 구분)</th><th>상위 기록</th>${data.columns.map(c=>`<th>${esc(c.name)} <button data-rename-col="${esc(c.id)}" title="열 이름 변경">✎</button><button data-delete-col="${esc(c.id)}" title="열 삭제">×</button></th>`).join('')}</tr></thead><tbody>${list.map(n=>`<tr data-id="${esc(n.id)}"><td><button data-select="${esc(n.id)}">열기</button></td><td contenteditable="true" data-field="title">${esc(n.title)}</td><td><select data-field="type"><option value="question" ${n.type==='question'?'selected':''}>질문</option><option value="answer" ${n.type==='answer'?'selected':''}>답변</option></select></td><td><select data-field="category">${catOptions(n.category)}</select></td><td contenteditable="true" data-field="body">${esc(n.body)}</td><td contenteditable="true" data-field="tags">${esc(n.tags.join(', '))}</td><td>${esc(data.nodes.find(p=>p.id===n.parent)?.title||'—')}</td>${data.columns.map(c=>`<td contenteditable="true" data-column="${esc(c.id)}">${esc(n.fields[c.id]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table><button class="table-add" id="addRow">＋ 행 추가</button>`;}
$('#all').onclick=()=>{category=null;render();};$('#categories').onclick=async e=>{const b=e.target.closest('[data-cat]'),edit=e.target.closest('[data-edit-cat]');if(b){category=b.dataset.cat;render();$('#viewport').scrollTo(0,0);}if(edit){const c=data.categories.find(c=>c.id===edit.dataset.editCat);const name=await ask('카테고리 이름',c.name);if(name?.trim()){checkpoint();c.name=name.trim();changed();}}};
$('#addCategory').onclick=async ()=>{const name=await ask('새 카테고리 이름 (예: 네이버, 데이터 분석)');if(!name?.trim())return;const parent=category&&await confirmAction(`“${catName(category)}” 아래에 하위 카테고리로 추가할까요?\n취소를 누르면 최상위 카테고리로 만듭니다.`)?category:null;checkpoint();const id=uid();data.categories.push({id,name:name.trim(),parent});category=id;changed();};
$('#newRoot').onclick=$('#emptyNew').onclick=()=>addNode();$('#mapTab').onclick=()=>{view='map';render();};$('#tableTab').onclick=()=>{view='table';render();};$('#search').oninput=e=>{query=e.target.value;renderBoard();if(view==='table')renderTable();$('#stats').textContent=`${visible().length}개 표시 · 전체 ${data.nodes.length}개 기록`;};
$('#editor').oninput=e=>{const n=node();if(!n)return;const field={editTitle:'title',editBody:'body'}[e.target.id];if(field){n[field]=e.target.value;persist();renderBoard();if(view==='table')renderTable();}};
$('#editor').onchange=e=>{const field={editType:'type',editCat:'category',editParent:'parent'}[e.target.id];if(field){checkpoint();node()[field]=e.target.value||null;changed();}};
$('#editor').onclick=async e=>{const n=node();if(!n)return;const t=e.target.closest('button');if(!t)return;if(t.id==='addTag'){const val=$('#tagInput').value.trim();if(val&&!n.tags.includes(val)){checkpoint();n.tags.push(val);changed();$('#tagInput').focus();}}if(t.dataset.removeTag!==undefined){checkpoint();n.tags.splice(Number(t.dataset.removeTag),1);changed();}if(t.id==='childAnswer')addNode(n.id,'answer');if(t.id==='childQuestion')addNode(n.id,'question');if(t.dataset.follow)addNode(n.id,'question',t.dataset.follow);if(t.id==='deleteNode'&&await confirmAction(`“${n.title}” 기록을 삭제할까요? 하위 기록은 유지됩니다.`)){checkpoint();data.nodes=data.nodes.filter(p=>p.id!==n.id);data.nodes.forEach(p=>{if(p.parent===n.id)p.parent=null;});selected=data.nodes[0]?.id;changed();}};
$('#editor').onkeydown=e=>{if(e.target.id==='tagInput'&&e.key==='Enter'){e.preventDefault();$('#addTag').click();}};
$('#nodes').onclick=e=>{if(e.target.closest('.tag'))return;const add=e.target.closest('[data-add]');if(add){addNode(add.dataset.add,'answer');return;}const card=e.target.closest('[data-id]');if(card){selected=card.dataset.id;renderEditor();document.querySelectorAll('.node').forEach(el=>el.classList.toggle('selected',el.dataset.id===selected));}};
$('#nodes').onkeydown=e=>{if(e.target.matches('.node')&&['Enter',' '].includes(e.key)){e.preventDefault();selected=e.target.dataset.id;render();}};
let drag=null,tagDrag=null;
$('#nodes').onpointerdown=e=>{if(e.button!==0||e.target.closest('button,.tag'))return;const card=e.target.closest('.node');if(!card)return;const n=data.nodes.find(n=>n.id===card.dataset.id);drag={n,card,x:e.clientX,y:e.clientY,ox:n.x,oy:n.y,moved:false};card.setPointerCapture(e.pointerId);};
$('#nodes').onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<4)return;if(!drag.moved)checkpoint();drag.moved=true;drag.n.x=Math.max(15,drag.ox+dx);drag.n.y=Math.max(15,drag.oy+dy);drag.card.style.left=drag.n.x+'px';drag.card.style.top=drag.n.y+'px';drawLines();};
function endDrag(){if(drag?.moved){persist();$('#board').style.width=Math.max(1100,...visible().map(n=>n.x+340))+'px';$('#board').style.height=Math.max(900,...visible().map(n=>n.y+330))+'px';}drag=null;}
$('#nodes').onpointerup=endDrag;$('#nodes').onpointercancel=endDrag;
$('#nodes').ondragstart=e=>{const tag=e.target.closest('[data-tag]');if(!tag)return;tagDrag={id:tag.closest('[data-id]').dataset.id,index:Number(tag.dataset.tag)};e.dataTransfer.setData('text/plain',tag.textContent);e.dataTransfer.effectAllowed='move';};
$('#nodes').ondragover=e=>{if(tagDrag){e.preventDefault();e.dataTransfer.dropEffect='move';e.target.closest('.node')?.classList.add('drag-over');}};$('#nodes').ondragleave=e=>e.target.closest('.node')?.classList.remove('drag-over');
$('#nodes').ondrop=e=>{e.preventDefault();const card=e.target.closest('.node');if(!card||!tagDrag)return;const from=data.nodes.find(n=>n.id===tagDrag.id),to=data.nodes.find(n=>n.id===card.dataset.id);if(from&&to&&from!==to){checkpoint();const val=from.tags.splice(tagDrag.index,1)[0];if(!to.tags.includes(val))to.tags.push(val);changed();toast('키워드를 옮겼습니다.');}tagDrag=null;document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));};$('#nodes').ondragend=()=>{tagDrag=null;document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));};
$('#arrange').onclick=()=>{checkpoint();const list=visible(),ids=new Set(list.map(n=>n.id));let row=0;function place(n,depth){n.x=65+depth*325;n.y=60+row++*195;list.filter(c=>c.parent===n.id).forEach(c=>place(c,depth+1));}list.filter(n=>!ids.has(n.parent)).forEach(n=>place(n,0));changed();$('#viewport').scrollTo(0,0);toast('현재 보이는 기록을 연결 순서로 정렬했습니다.');};
$('#tableView').addEventListener('input',e=>{const cell=e.target.closest('[contenteditable]');if(!cell)return;const n=data.nodes.find(n=>n.id===cell.closest('tr').dataset.id);const val=cell.innerText;if(cell.dataset.column)n.fields[cell.dataset.column]=val;else n[cell.dataset.field]=cell.dataset.field==='tags'?[...new Set(val.split(',').map(s=>s.trim()).filter(Boolean))]:val;persist();renderBoard();renderEditor();});
$('#tableView').onchange=e=>{if(!e.target.matches('select'))return;checkpoint();const n=data.nodes.find(n=>n.id===e.target.closest('tr').dataset.id);n[e.target.dataset.field]=e.target.value;changed();};
$('#tableView').onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select){selected=b.dataset.select;renderEditor();}if(b.id==='addRow')addNode(null,'answer');if(b.dataset.renameCol){const c=data.columns.find(c=>c.id===b.dataset.renameCol);const name=await ask('열 이름',c.name);if(name?.trim()){checkpoint();c.name=name.trim();changed();}}if(b.dataset.deleteCol&&await confirmAction('이 열과 해당 열의 내용을 삭제할까요?')){checkpoint();const id=b.dataset.deleteCol;data.columns=data.columns.filter(c=>c.id!==id);data.nodes.forEach(n=>delete n.fields[id]);changed();}};
$('#addColumn').onclick=async ()=>{const name=await ask('추가할 열 이름 (예: 성과 지표, 기간, 참고 링크)');if(name?.trim()){checkpoint();data.columns.push({id:uid(),name:name.trim()});changed();}};
function renderBank(){$('#bankFilters').innerHTML=['전체',...new Set(bank.map(q=>q[0]))].map(c=>`<button class="${c===bankFilter?'active':''}" data-bank-cat="${esc(c)}">${esc(c)}</button>`).join('');$('#bankList').innerHTML=bank.map((q,i)=>({q,i})).filter(({q})=>bankFilter==='전체'||q[0]===bankFilter).map(({q,i})=>`<button class="bank-item" data-bank="${i}"><span>${esc(q[1])}</span><small>${esc(q[0])} ＋</small></button>`).join('');}
$('#library').onclick=()=>{renderBank();$('#libraryDialog').showModal();};$('#closeLibrary').onclick=()=>$('#libraryDialog').close();$('#bankFilters').onclick=e=>{const b=e.target.closest('[data-bank-cat]');if(b){bankFilter=b.dataset.bankCat;renderBank();}};$('#bankList').onclick=e=>{const b=e.target.closest('[data-bank]');if(b){$('#libraryDialog').close();addNode(null,'question',bank[Number(b.dataset.bank)][1]);}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`갈피-경험기록-${new Date().toLocaleDateString('sv-SE')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('JSON 저장을 요청했습니다. 브라우저 다운로드를 확인하세요.');};
async function importFile(file){try{if(file.size>10000000)throw Error('10MB 이하의 JSON 파일을 선택해 주세요.');const next=validate(JSON.parse(await file.text()));if(!await confirmAction(`기록 ${next.nodes.length}개를 불러옵니다. 현재 기록을 교체할까요?\n필요하면 취소 후 현재 기록을 JSON으로 저장해 주세요.`))return;checkpoint();data=next;category=null;query='';$('#search').value='';selected=data.nodes[0]?.id;changed();toast('JSON 기록을 불러왔습니다.');}catch(err){toast('불러오기 실패: '+err.message);}}
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(file)await importFile(file);e.target.value='';};
// JSON 파일을 화면에 끌어다 놓아도 불러온다. 키워드를 다른 카드로 끄는 것과는 파일이 실려 있는지로 구분한다.
let fileDrag=0;const hasFiles=e=>[...(e.dataTransfer?.types||[])].includes('Files');
window.addEventListener('dragenter',e=>{if(!hasFiles(e))return;e.preventDefault();fileDrag++;$('#dropOverlay').hidden=false;});
window.addEventListener('dragover',e=>{if(!hasFiles(e))return;e.preventDefault();e.dataTransfer.dropEffect='copy';});
window.addEventListener('dragleave',e=>{if(!hasFiles(e))return;fileDrag=Math.max(0,fileDrag-1);if(!fileDrag)$('#dropOverlay').hidden=true;});
window.addEventListener('drop',e=>{if(!hasFiles(e))return;e.preventDefault();fileDrag=0;$('#dropOverlay').hidden=true;const file=[...e.dataTransfer.files].find(f=>/\.json$/i.test(f.name)||f.type==='application/json');if(file)importFile(file);else toast('갈피에서 저장한 JSON 파일을 놓아 주세요.');});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('input,textarea,[contenteditable="true"]')){e.preventDefault();if(history.length){data=JSON.parse(history.pop());if(!data.categories.some(c=>c.id===category))category=null;if(!node())selected=data.nodes[0]?.id;changed();toast('마지막 구조 변경을 되돌렸습니다.');}}});
render();
